// ── Types ──────────────────────────────────────────────────────────────────

type ChatTurn =
  | { role: 'user'; content: string; ts: number }
  | { role: 'assistant'; content: string; ts: number }
  | { role: 'assistant'; content: ''; loading: true; ts: number };

interface Conversation {
  turns: ChatTurn[];
}

type Tone = 'friendly' | 'direct' | 'playful';
type LangPref = 'auto' | 'pt' | 'en';
type MaxTokens = 256 | 512 | 1024 | 2048;

interface ConvSettings {
  tone: Tone;
  language: LangPref;
  maxTokens: MaxTokens;
}

