// ── Props ───────────────────────────────────────────────────────────────────

interface AppProps {
  topBarRight?: React.ReactNode;
}

// ── Suggestion config ───────────────────────────────────────────────────────

type SuggestionIconName = 'sparkle' | 'code' | 'book' | 'message';

const SUGGESTION_ICONS: SuggestionIconName[] = [
  'sparkle', 'code', 'book', 'message',
];

// ── Component ───────────────────────────────────────────────────────────────

export default function App({ topBarRight }: AppProps) {
  const [locale] = useLocale();
  const t = useMemo(() => createT(locale as Locale, APP_KEYS), [locale]);

  // ── Auth / key ──────────────────────────────────────────────────────────
  const [groqKey, setGroqKey] = useState<string | null>(null);
  const [keyLoaded, setKeyLoaded] = useState(false);

  useEffect(() => {
    resolveGroqKey().then((k) => {
      setGroqKey(k);
      setKeyLoaded(true);
    }).catch(() => setKeyLoaded(true));
  }, []);

  // ── Settings ────────────────────────────────────────────────────────────
  const [settings, setSettings] = useState<ConvSettings>({
    tone: 'friendly',
    language: 'auto',
    maxTokens: 1024,
  });
  const [showSettings, setShowSettings] = useState(false);
  const settingsRef = useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    Promise.all([
      getSetting(KEY_TONE),
      getSetting(KEY_LANGUAGE),
      getSetting(KEY_MAX_TOKENS),
    ]).then(([tone, lang, maxTok]) => {
      setSettings({
        tone: (tone as Tone) ?? 'friendly',
        language: (lang as LangPref) ?? 'auto',
        maxTokens: maxTok ? (parseInt(maxTok, 10) as MaxTokens) : 1024,
      });
    }).catch(() => undefined);
  }, []);

  const updateSettings = useCallback(
    async (patch: Partial<ConvSettings>) => {
      const next = { ...settings, ...patch };
      setSettings(next);
      if (patch.tone !== undefined) await putSetting(KEY_TONE, patch.tone);
      if (patch.language !== undefined) await putSetting(KEY_LANGUAGE, patch.language);
      if (patch.maxTokens !== undefined)
        await putSetting(KEY_MAX_TOKENS, String(patch.maxTokens));
    },
    [settings],
  );

  // Close settings on outside click
  useEffect(() => {
    if (!showSettings) return;
    const handler = (e: MouseEvent) => {
      if (settingsRef.current && !settingsRef.current.contains(e.target as Node)) {
        setShowSettings(false);
      }
    };
    document.addEventListener('mousedown', handler);
    return () => document.removeEventListener('mousedown', handler);
  }, [showSettings]);

  // ── Conversations ────────────────────────────────────────────────────────
  const [docs, setDocs] = useState<SavedDoc[]>([]);
  const [activeDocId, setActiveDocId] = useState<string | null>(null);
  const [turns, setTurns] = useState<ChatTurn[]>([]);
  const [convTitleVal, setConvTitleVal] = useState('');
  const turnsRef = useRef<ChatTurn[]>([]);

  // Keep ref in sync
  useEffect(() => { turnsRef.current = turns; }, [turns]);

  const refreshDocs = useCallback(async () => {
    const all = await listDocs('ask');
    setDocs(all);
    return all;
  }, []);

  useEffect(() => {
    const init = async () => {
      const all = await refreshDocs();
      const savedId = await getSetting(KEY_ACTIVE);
      const target = savedId ? all.find((d) => d.id === savedId) : null;
      if (target) {
        activateDoc(target);
      }
    };
    init().catch(() => undefined);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  function activateDoc(doc: SavedDoc) {
    try {
      const parsed = JSON.parse(doc.content) as Conversation;
      setTurns(parsed.turns ?? []);
    } catch {
      setTurns([]);
    }
    setActiveDocId(doc.id);
    setConvTitleVal(doc.name);
    putSetting(KEY_ACTIVE, doc.id).catch(() => undefined);
  }

  function startNewConversation() {
    setTurns([]);
    setActiveDocId(null);
    setConvTitleVal('');
    putSetting(KEY_ACTIVE, '').catch(() => undefined);
  }

  const persistTurns = useCallback(
    async (nextTurns: ChatTurn[], docId: string | null, titleOverride?: string) => {
      const content = JSON.stringify({ turns: nextTurns });
      const title =
        titleOverride ??
        (nextTurns.find((tt) => tt.role === 'user')
          // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
          ? (nextTurns.find((tt) => tt.role === 'user') as { role: 'user'; content: string }).content.slice(0, 50)
          : t('ask.untitled'));

      if (docId) {
        await updateDoc(docId, title, content);
      } else {
        const newId = await saveDoc('ask', title, content);
        setActiveDocId(newId);
        await putSetting(KEY_ACTIVE, newId);
        return newId;
      }
      return docId;
    },
    [t],
  );

  const handleDeleteDoc = useCallback(async (id: string) => {
    await deleteDoc(id);
    if (id === activeDocId) {
      startNewConversation();
    }
    await refreshDocs();
  }, [activeDocId, refreshDocs]);

  // ── Chat / ask ───────────────────────────────────────────────────────────
  const [inputValue, setInputValue] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [turnError, setTurnError] = useState<string | null>(null);
  const [inputFocused, setInputFocused] = useState(false);
  const abortRef = useRef<AbortController | null>(null);
  const textareaRef = useRef<HTMLTextAreaElement | null>(null);
  const chatEndRef = useRef<HTMLDivElement | null>(null);

  // Auto-resize textarea
  useLayoutEffect(() => {
    const el = textareaRef.current;
    if (!el) return;
    el.style.height = 'auto';
    el.style.height = `${Math.min(el.scrollHeight, 192)}px`;
  }, [inputValue]);

  // Scroll to bottom on new turns
  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [turns, isLoading]);

  const submitMessage = useCallback(
    async (text: string) => {
      if (!groqKey || !text.trim() || isLoading) return;
      const content = text.trim();
      setInputValue('');
      setTurnError(null);

      const userTurn: ChatTurn = { role: 'user', content, ts: Date.now() };
      const loadingTurn: ChatTurn = { role: 'assistant', content: '', loading: true, ts: Date.now() };
      const nextTurns = [...turnsRef.current, userTurn, loadingTurn];
      setTurns(nextTurns);
      setIsLoading(true);

      // History for context (completed turns only)
      const history = turnsRef.current
        .filter(
          (turn): turn is { role: 'user' | 'assistant'; content: string; ts: number } =>
            !('loading' in turn),
        )
        .map((turn) => ({ role: turn.role as 'user' | 'assistant', content: turn.content }))
        .slice(-6);

      const effectiveLang: Locale =
        settings.language === 'auto'
          ? (locale as Locale)
          : (settings.language as Locale);

      abortRef.current?.abort();
      const ac = new AbortController();
      abortRef.current = ac;

      try {
        // TODO: streaming
        const answer = await askGroq(content, {
          key: groqKey,
          system: buildSystem(settings.tone, effectiveLang, settings.language),
          locale: effectiveLang,
          signal: ac.signal,
          history,
          maxTokens: settings.maxTokens,
        });

        if (ac.signal.aborted) return;

        const answerTurn: ChatTurn = { role: 'assistant', content: answer, ts: Date.now() };
        const finalTurns = [
          ...turnsRef.current.filter((turn) => !('loading' in turn)),
          answerTurn,
        ];
        setTurns(finalTurns);

        const newDocId = await persistTurns(finalTurns, activeDocId);
        if (newDocId && newDocId !== activeDocId) {
          setActiveDocId(newDocId as string);
          setConvTitleVal(finalTurns.find((tt) => tt.role === 'user') ? content.slice(0, 50) : t('ask.untitled'));
        }
        await refreshDocs();
      } catch (err) {
        if (ac.signal.aborted) return;
        const msg = err instanceof Error ? err.message : String(err);
        setTurnError(msg);
        // Remove the loading turn
        setTurns((prev) => prev.filter((turn) => !('loading' in turn)));
      } finally {
        if (!ac.signal.aborted) setIsLoading(false);
      }
    },
    [
      groqKey,
      isLoading,
      locale,
      settings,
      activeDocId,
      persistTurns,
      refreshDocs,
      t,
    ],
  );

  const handleStop = useCallback(() => {
    abortRef.current?.abort();
    setIsLoading(false);
    setTurns((prev) => prev.filter((turn) => !('loading' in turn)));
  }, []);

  // ── Keyboard shortcuts ───────────────────────────────────────────────────
  useEffect(() => {
    const handler = (e: KeyboardEvent) => {
      // Cmd/Ctrl+N → new conversation (never Cmd+K — shell owns that)
      if ((e.metaKey || e.ctrlKey) && e.key === 'n') {
        e.preventDefault();
        startNewConversation();
        textareaRef.current?.focus();
      }
    };
    document.addEventListener('keydown', handler);
    return () => document.removeEventListener('keydown', handler);
  }, []);

  const handleTextareaKeyDown = useCallback(
    (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
      if (e.key === 'Enter' && !e.shiftKey) {
        e.preventDefault();
        void submitMessage(inputValue);
        return;
      }
      if (e.key === 'Escape') {
        if (inputValue) {
          setInputValue('');
        } else {
          e.currentTarget.blur();
        }
      }
    },
    [inputValue, submitMessage],
  );

  // ── Sidebar time-grouped list ─────────────────────────────────────────────

  const groupedDocs = useMemo(() => {
    const groups: Record<ConvGroup, SavedDoc[]> = {
      today: [], yesterday: [], last7: [], older: [],
    };
    for (const doc of docs) {
      groups[getConvGroup(doc.savedAt)].push(doc);
    }
    return groups;
  }, [docs]);

  const GROUP_ORDER: ConvGroup[] = ['today', 'yesterday', 'last7', 'older'];
  const GROUP_LABEL_KEY: Record<ConvGroup, string> = {
    today: 'ask.group.today',
    yesterday: 'ask.group.yesterday',
    last7: 'ask.group.last7',
    older: 'ask.group.older',
  };

  const sidebar = (
    <SidebarWrap>
      <SidebarTopRow>
        <Button
          variant="primary"
          onClick={startNewConversation}
          style={{ width: '100%', justifyContent: 'center' }}
        >
          {t('ask.sidebar.new')}
        </Button>
      </SidebarTopRow>
      <ConvList>
        {docs.length === 0 ? (
          <SidebarEmpty>{t('ask.sidebar.empty')}</SidebarEmpty>
        ) : (
          GROUP_ORDER.map((group) => {
            const groupDocs = groupedDocs[group];
            if (groupDocs.length === 0) return null;
            return (
              <div key={group}>
                <ConvGroupHeader>
                  <Eyebrow>{t(GROUP_LABEL_KEY[group])}</Eyebrow>
                </ConvGroupHeader>
                {groupDocs.map((doc) => (
                  <ConvRow
                    key={doc.id}
                    active={doc.id === activeDocId}
                    onClick={() => activateDoc(doc)}
                  >
                    <ConvRowTitle active={doc.id === activeDocId}>
                      {doc.name || t('ask.untitled')}
                    </ConvRowTitle>
                    <ConvRowMeta>
                      {localizedTimeAgo(new Date(doc.savedAt).toISOString(), t)}
                    </ConvRowMeta>
                    <ConvRowHover className="conv-row-hover">
                      <IconButton
                        title={t('ask.sidebar.delete')}
                        tone="danger"
                        onClick={(e) => {
                          e.stopPropagation();
                          void handleDeleteDoc(doc.id);
                        }}
                      >
                        <Icon name="close" size={12} />
                      </IconButton>
                    </ConvRowHover>
                  </ConvRow>
                ))}
              </div>
            );
          })
        )}
      </ConvList>
    </SidebarWrap>
  );

  // ── No key state ─────────────────────────────────────────────────────────

  if (keyLoaded && !groqKey) {
    return (
      <Layout title={t('ask.title')} sidebar={sidebar} topBarRight={topBarRight}>
        <NoKeyCard>
          <NoKeyIcon>
            <Icon name="sparkle" size={24} />
          </NoKeyIcon>
          <NoKeyTitle>{t('ask.noKey.title')}</NoKeyTitle>
          <NoKeyBody>{t('ask.noKey.body')}</NoKeyBody>
          <Button
            variant="primary"
            onClick={() => { window.location.hash = '#/settings'; }}
          >
            {t('ask.noKey.cta')}
          </Button>
        </NoKeyCard>
      </Layout>
    );
  }

  // ── Settings popover ─────────────────────────────────────────────────────

  const settingsPopover = (
    <div style={{ position: 'relative' }} ref={settingsRef}>
      <IconButton
        title={t('ask.settings.title')}
        active={showSettings}
        onClick={() => setShowSettings((v) => !v)}
      >
        <Icon name="settings" size={16} />
      </IconButton>
      {showSettings && (
        <SettingsPopover>
          <SettingsGroup>
            <SettingsLabel>{t('ask.settings.tone')}</SettingsLabel>
            <SettingsSelect
              value={settings.tone}
              onChange={(e) => void updateSettings({ tone: e.target.value as Tone })}
            >
              <option value="friendly">{t('ask.settings.tone.friendly')}</option>
              <option value="direct">{t('ask.settings.tone.direct')}</option>
              <option value="playful">{t('ask.settings.tone.playful')}</option>
            </SettingsSelect>
          </SettingsGroup>
          <SettingsGroup>
            <SettingsLabel>{t('ask.settings.language')}</SettingsLabel>
            <SettingsSelect
              value={settings.language}
              onChange={(e) => void updateSettings({ language: e.target.value as LangPref })}
            >
              <option value="auto">{t('ask.settings.language.auto')}</option>
              <option value="pt">{t('ask.settings.language.pt')}</option>
              <option value="en">{t('ask.settings.language.en')}</option>
            </SettingsSelect>
          </SettingsGroup>
          <SettingsGroup>
            <SettingsLabel>{t('ask.settings.maxTokens')}</SettingsLabel>
            <SettingsSelect
              value={settings.maxTokens}
              onChange={(e) =>
                void updateSettings({ maxTokens: parseInt(e.target.value, 10) as MaxTokens })
              }
            >
              <option value={256}>{t('ask.settings.maxTokens.short')}</option>
              <option value={512}>{t('ask.settings.maxTokens.medium')}</option>
              <option value={1024}>{t('ask.settings.maxTokens.long')}</option>
              <option value={2048}>{t('ask.settings.maxTokens.xlong')}</option>
            </SettingsSelect>
          </SettingsGroup>
        </SettingsPopover>
      )}
    </div>
  );

  // ── Render ────────────────────────────────────────────────────────────────

  const isEmpty = turns.length === 0 && !isLoading;
  const isInputReady = !!inputValue.trim() && !isLoading && !!groqKey;

  const SUGGESTION_KEYS = ['1', '2', '3', '4'] as const;

  return (
    <Layout
      title={t('ask.title')}
      sidebar={sidebar}
      topBarRight={topBarRight}
    >
      <ChatArea>
        {/* Top bar: title input + settings cog */}
        <ChatTopBar>
          <TitleInput
            value={convTitleVal}
            placeholder={t('ask.untitled')}
            onChange={(e) => setConvTitleVal(e.target.value)}
            onBlur={async () => {
              if (activeDocId && convTitleVal.trim()) {
                const content = JSON.stringify({ turns: turnsRef.current });
                await updateDoc(activeDocId, convTitleVal.trim(), content);
                await refreshDocs();
              }
            }}
          />
          {settingsPopover}
        </ChatTopBar>

        {/* Scrollable message area */}
        <ChatScroll>
          {isEmpty ? (
            /* ── Welcome state ─────────────────────────────────────────── */
            <ConvColumn>
              <WelcomeWrap>
                <WelcomeTitle>{t('ask.welcome.title')}</WelcomeTitle>
                <WelcomeKicker>{t('ask.welcome.kicker')}</WelcomeKicker>
                <SuggestionsGrid>
                  {SUGGESTION_KEYS.map((n, i) => (
                    <SuggestionCard
                      key={n}
                      onClick={() => {
                        const prompt = t(`ask.suggestion.${n}`);
                        setInputValue(prompt);
                        textareaRef.current?.focus();
                        void submitMessage(prompt);
                      }}
                    >
                      <SuggestionIcon>
                        <Icon name={SUGGESTION_ICONS[i]} size={18} aria-hidden />
                      </SuggestionIcon>
                      <SuggestionTitle>{t(`ask.suggestion.${n}.title`)}</SuggestionTitle>
                      <SuggestionBody>{t(`ask.suggestion.${n}.body`)}</SuggestionBody>
                    </SuggestionCard>
                  ))}
                </SuggestionsGrid>
              </WelcomeWrap>
            </ConvColumn>
          ) : (
            /* ── Conversation turns ────────────────────────────────────── */
            <ConvColumn>
              {turns.map((turn, i) => {
                const isUser = turn.role === 'user';
                const isLoadingTurn = 'loading' in turn && turn.loading;

                return (
                  <TurnBlock key={i} user={isUser}>
                    {isUser ? (
                      /* User bubble */
                      <>
                        <UserBubble>{turn.content}</UserBubble>
                        <TurnTs>{formatTs(turn.ts, t)}</TurnTs>
                        <TurnActions className="turn-actions">
                          {/* TODO: edit handler — fills input + truncates conv */}
                          <IconButton
                            title={t('ask.action.edit')}
                            onClick={() => {/* TODO */}}
                          >
                            <Icon name="edit" size={13} />
                          </IconButton>
                        </TurnActions>
                      </>
                    ) : (
                      /* Assistant frame */
                      <AssistantFrame>
                        <AssistantHeader>
                          <AssistantAvatar aria-hidden>
                            <Icon name="sparkle" size={14} />
                          </AssistantAvatar>
                          <AssistantLabel>{t('ask.atlantis')}</AssistantLabel>
                        </AssistantHeader>
                        {isLoadingTurn ? (
                          <ThinkingDots aria-label={t('ask.thinking')}>
                            <span /><span /><span />
                          </ThinkingDots>
                        ) : (
                          <>
                            <MarkdownBody>{turn.content}</MarkdownBody>
                            <TurnTs>{formatTs(turn.ts, t)}</TurnTs>
                            <TurnActions className="turn-actions">
                              <IconButton
                                title={t('ask.action.copy')}
                                onClick={() => {
                                  if (turn.role === 'assistant' && !('loading' in turn)) {
                                    void navigator.clipboard.writeText(turn.content);
                                  }
                                }}
                              >
                                <Icon name="copy" size={13} />
                              </IconButton>
                              <IconButton
                                title={t('ask.action.regenerate')}
                                onClick={() => {
                                  const lastUser = turnsRef.current
                                    .filter((tt) => tt.role === 'user')
                                    .pop();
                                  if (lastUser && lastUser.role === 'user') {
                                    void submitMessage(lastUser.content);
                                  }
                                }}
                              >
                                <Icon name="refresh" size={13} />
                              </IconButton>
                            </TurnActions>
                          </>
                        )}
                      </AssistantFrame>
                    )}
                  </TurnBlock>
                );
              })}

              {/* Error block */}
              {turnError && (
                <TurnBlock>
                  <AssistantFrame>
                    <AssistantHeader>
                      <AssistantAvatar aria-hidden>
                        <Icon name="sparkle" size={14} />
                      </AssistantAvatar>
                      <AssistantLabel>{t('ask.atlantis')}</AssistantLabel>
                    </AssistantHeader>
                    <ErrorLine>{turnError}</ErrorLine>
                    <Button
                      variant="ghost"
                      onClick={() => {
                        const last = turnsRef.current
                          .filter((tt) => tt.role === 'user')
                          .pop();
                        if (last && last.role === 'user') {
                          void submitMessage(last.content);
                        }
                      }}
                    >
                      {t('ask.retry')}
                    </Button>
                  </AssistantFrame>
                </TurnBlock>
              )}

              <div ref={chatEndRef} />
            </ConvColumn>
          )}
        </ChatScroll>

        {/* Floating input pill */}
        <InputBarOuter>
          <InputBarInner>
            <PillWrap focused={inputFocused}>
              <Textarea
                ref={textareaRef}
                rows={1}
                placeholder={t('ask.placeholder')}
                value={inputValue}
                onChange={(e) => setInputValue(e.target.value)}
                onKeyDown={handleTextareaKeyDown}
                onFocus={() => setInputFocused(true)}
                onBlur={() => setInputFocused(false)}
                disabled={isLoading}
                aria-label={t('ask.placeholder')}
              />

              {isLoading ? (
                <StopBtn
                  type="button"
                  aria-label={t('ask.stop')}
                  title={t('ask.stop')}
                  onClick={handleStop}
                >
                  <Icon name="square" size={14} />
                </StopBtn>
              ) : (
                <SendBtn
                  type="button"
                  ready={isInputReady}
                  aria-label={t('ask.send')}
                  title={t('ask.send')}
                  disabled={!isInputReady}
                  onClick={() => void submitMessage(inputValue)}
                >
                  <Icon name="send" size={15} />
                </SendBtn>
              )}
            </PillWrap>

            <InputHints>
              <HintSpan>
                <Kbd>↵</Kbd> {t('ask.hint.send')}
              </HintSpan>
              <HintSpan>
                <Kbd>⇧↵</Kbd> {t('ask.hint.newline')}
              </HintSpan>
              <HintSpan>
                <Kbd>⌘N</Kbd> {t('ask.hint.newConv')}
              </HintSpan>
            </InputHints>
          </InputBarInner>
        </InputBarOuter>
      </ChatArea>
    </Layout>
  );
}
